export const create = mutation({
  args: {
    taskId: v.id("tasks"),
    fromAgentId: v.optional(v.id("agents")),
    fromName: v.optional(v.string()),
    content: v.string(),
    isSystemMessage: v.optional(v.boolean()),
  },
  handler: async (ctx, args) => {
    // Parse @mentions from content
    const mentionRegex = /@(\w+)/g;
    const mentions: string[] = [];
    let match;
    while ((match = mentionRegex.exec(args.content)) !== null) {
      mentions.push(match[1].toLowerCase());
    }

    // Resolve mentioned agent IDs
    const mentionedAgentIds: string[] = [];
    if (mentions.length > 0) {
      const allAgents = await ctx.db.query("agents").collect();
      for (const mention of mentions) {
        const agent = allAgents.find(
          (a) => a.name.toLowerCase() === mention
        );
        if (agent) {
          mentionedAgentIds.push(agent._id);
        }
      }
    }

    const messageId = await ctx.db.insert("messages", {
      taskId: args.taskId,
      fromAgentId: args.fromAgentId,
      fromName: args.fromName ?? "System",
      content: args.content,
      mentionedAgentIds:
        mentionedAgentIds.length > 0
          ? (mentionedAgentIds as any)
          : undefined,
      isSystemMessage: args.isSystemMessage,
    });

    // Update task comment count
    const task = await ctx.db.get(args.taskId);
    if (task) {
      await ctx.db.patch(args.taskId, {
        commentCount: (task.commentCount ?? 0) + 1,
        lastAssigneeUpdateAt: Date.now(),
      });
    }

    // Create notifications for mentions
    for (const agentId of mentionedAgentIds) {
      const task = await ctx.db.get(args.taskId);
      await ctx.db.insert("notifications", {
        mentionedAgentId: agentId as any,
        content: `${args.fromName ?? "Someone"} mentioned you in ${task?.title ?? "a task"}: "${args.content.slice(0, 100)}"`,
        taskId: args.taskId,
        taskTitle: task?.title,
        fromAgentId: args.fromAgentId,
        fromAgentName: args.fromName,
        delivered: false,
      });
    }

    // Log activity
    const task2 = await ctx.db.get(args.taskId);
    await ctx.db.insert("activities", {
      type: "message_sent",
      agentId: args.fromAgentId,
      agentName: args.fromName,
      taskId: args.taskId,
      taskTitle: task2?.title,
      message: `${args.fromName ?? "Someone"} commented on '${task2?.title ?? "a task"}'`,
    });

    return messageId;
  },
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const listByAgent = query({
  args: {
    agentId: v.id("agents"),
    delivered: v.optional(v.boolean()),
  },
  handler: async (ctx, args) => {
    const notifications = await ctx.db
      .query("notifications")
      .withIndex("by_agent", (q) => q.eq("mentionedAgentId", args.agentId))
      .order("desc")
      .take(20);

    if (args.delivered !== undefined) {
      return notifications.filter((n) => n.delivered === args.delivered);
    }
    return notifications;
  },
});

export const markDelivered = mutation({
  args: { id: v.id("notifications") },
  handler: async (ctx, args) => {
    await ctx.db.patch(args.id, { delivered: true });
  },
});

export const markAllDelivered = mutation({
  args: { agentId: v.id("agents") },
  handler: async (ctx, args) => {
    const undelivered = await ctx.db
      .query("notifications")
      .withIndex("by_agent", (q) => q.eq("mentionedAgentId", args.agentId))
      .collect();

    for (const n of undelivered.filter((n) => !n.delivered)) {
      await ctx.db.patch(n._id, { delivered: true });
    }
  },
});

